import {useCallback, useState} from 'react'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useNavigate} from '@github-ui/use-navigate'
import {subagentsRoute} from './subagents-route'
import {CopilotIcon} from '@primer/octicons-react'
import {Breadcrumbs, Button, PageHeader, Select, Spinner} from '@primer/react'
import {Status, type CustomAgent, type ExtendedBaseOrganization, type Ruleset} from '../types'
import {OrgSelector, simpleOrgLoader} from '@github-ui/org-selector'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

const customAgents: CustomAgent[] = [
  {
    name: 'Rails API Developer',
    status: Status.enabled,
    organization: {
      name: 'copilot-agents',
    },
    repository: {
      name: '.github-private',
    },
  },
  {
    name: 'Python V2 Developer',
    status: Status.disabled,
    organization: {
      name: 'repos-security',
    },
    repository: {
      name: '.github-private',
    },
  },
]

export function Subagents() {
  const navigate = useNavigate()
  const payload = useRouteQuery(subagentsRoute, 'mainQuery')
  const [sourceOrganization, setSourceOrganization] = useState<ExtendedBaseOrganization | undefined>(
    payload.data.organizations[0] ?? undefined,
  )
  const [isCreatingRuleset, setCreatingRuleset] = useState(false)

  const {
    isLoading,
    data: ruleset,
    refetch: refetchRuleset,
  } = useQuery({
    queryKey: ['copilot-agent-plane', 'ruleset', payload.data.paths.showRuleset, sourceOrganization],
    queryFn: async () => {
      const url = `${payload.data.paths.showRuleset}?organization_id=${sourceOrganization ? sourceOrganization.id : ''}`
      const response = await verifiedFetchJSON(url)

      if (!response.ok) {
        throw new Error(`Failed to fetch ruleset (${response.status} on ${response.url})`)
      }

      const json = await response.json()
      if (!json.success) {
        throw new Error(`Failed to fetch ruleset: ${json.message}`)
      }

      return json.ruleset as Ruleset
    },
  })

  const protectAgentFiles = useCallback(async () => {
    if (!sourceOrganization) {
      return
    }
    setCreatingRuleset(true)
    await verifiedFetchJSON(payload.data.paths.createRuleset, {
      method: 'POST',
      body: {
        organization_id: sourceOrganization.id,
      },
    })
    refetchRuleset()
    setCreatingRuleset(false)
  }, [sourceOrganization, payload.data.paths.createRuleset, refetchRuleset])

  return (
    <div className="d-flex flex-column gap-3">
      <Breadcrumbs>
        <Breadcrumbs.Item href="./">Agents</Breadcrumbs.Item>
        <Breadcrumbs.Item selected>Enable custom agents</Breadcrumbs.Item>
      </Breadcrumbs>
      <PageHeader>
        <PageHeader.TitleArea>
          <PageHeader.Title>Enable custom agents</PageHeader.Title>
        </PageHeader.TitleArea>
        <PageHeader.Description>
          <span className="fgColor-muted">
            Manage configurations for agents and track audit logs. Enable custom agents by re-using existing
            configurations in your organization. Learn more about custom agents.
          </span>
        </PageHeader.Description>
      </PageHeader>
      <div className="Box">
        <div className="Box-header d-flex flex-row flex-items-center flex-justify-between py-2">
          <span className="Box-title text-normal">Source organization</span>
        </div>
        <div className="Box-row d-flex flex-row flex-justify-between flex-items-center">
          <span className="flex-1">
            Select an organization with custom agent configuration files. Custom agents are sourced from a repository
            named <code>.github-private</code>.
          </span>
          <span className="flex-1 d-flex flex-justify-end">
            <OrgSelector
              selection={sourceOrganization}
              orgLoader={simpleOrgLoader<ExtendedBaseOrganization>(payload.data.organizations)}
              selectionVariant="single"
              selectOrg={setSourceOrganization}
              removeOrg={() => {
                setSourceOrganization(undefined)
              }}
            />
          </span>
        </div>
      </div>
      <div className="Box">
        <div className="Box-header d-flex flex-row flex-items-center flex-justify-between py-2">
          <span className="Box-title text-normal">{customAgents.length} Custom Agents</span>
        </div>
        {customAgents.map(agent => (
          <div key={agent.name} className="Box-row d-flex flex-row flex-justify-between">
            <div className="d-flex flex-row flex-items-center gap-1">
              <CopilotIcon />
              <span className="text-bold">{agent.name}</span>
              <span className="d-flex flex-row flex-items-center gap-1 fgColor-muted text-small">
                <span className="text-semibold">@{agent.organization.name}</span>
                <span>/</span>
                <span>{agent.repository.name}</span>
              </span>
            </div>
            <Select defaultValue={agent.status} aria-label="Custom agent status">
              <Select.Option value={Status.enabled}>Enabled</Select.Option>
              <Select.Option value={Status.disabled}>Disabled</Select.Option>
            </Select>
          </div>
        ))}
      </div>
      <div className="Box">
        <div className="Box-header d-flex flex-row flex-items-center flex-justify-between py-2">
          <span className="Box-title text-normal">Protect agent files using rulesets</span>
        </div>
        <div className="Box-row d-flex flex-row flex-items-center flex-justify-between">
          <span>
            {ruleset
              ? `Only enterprise owners can edit agent files in @${sourceOrganization?.name} / .github-private`
              : `Create a ruleset that only allows enterprise owners to edit agent source code.`}
          </span>
          {isLoading ? (
            <Spinner />
          ) : (
            <Button
              disabled={isCreatingRuleset}
              onClick={() => {
                if (ruleset) {
                  navigate(ruleset.url)
                } else {
                  protectAgentFiles()
                }
              }}
            >
              {ruleset ? `Edit ruleset` : `Protect agent files`}
            </Button>
          )}
        </div>
      </div>
      <div className="d-flex flex-justify-end gap-2">
        <Button onClick={() => navigate('./')}>Cancel</Button>
        <Button variant="primary" onClick={() => navigate('./')}>
          Save
        </Button>
      </div>
    </div>
  )
}

try{ Subagents.displayName ||= 'Subagents' } catch {}