import {useMemo} from 'react'
import {MeterIcon, PlayIcon, ShieldIcon, SkipIcon, type Icon as PrimerIcon} from '@primer/octicons-react'
import {EnterpriseControlGroup} from '@github-ui/enterprise-control-group'
import type {Enforcement, Ruleset} from '../types'
import {useRuleset} from '../hooks/use-ruleset'

export type ProtectAgentsProps = {
  canAdmin?: boolean
  canWrite?: boolean
}

export function ProtectAgents({canAdmin = false, canWrite = false}: ProtectAgentsProps) {
  const {ruleset, isLoading, createRuleset} = useRuleset()
  const title = ruleset ? `Only enterprise admins can edit agent files` : 'Protect agent files using rulesets'

  const disableAction = useMemo(() => {
    // No ruleset associated, and no write/admin permission
    if (!ruleset && !(canWrite || canAdmin)) {
      return true
    }
    // Ruleset associated but no admin permission
    if (ruleset && !canAdmin) {
      return true
    }
    return false
  }, [ruleset, canAdmin, canWrite])

  return (
    <EnterpriseControlGroup>
      <EnterpriseControlGroup.Item
        leadingVisual={<RulesetEnforcement ruleset={ruleset} />}
        href={canAdmin && ruleset ? ruleset.url : undefined}
        disabled={disableAction}
      >
        <EnterpriseControlGroup.Title>{title}</EnterpriseControlGroup.Title>
        <EnterpriseControlGroup.Description>
          <RulesetSummary ruleset={ruleset} />
        </EnterpriseControlGroup.Description>
        {ruleset ? (
          <EnterpriseControlGroup.LinkLabel aria-disabled={disableAction}>
            Edit ruleset
          </EnterpriseControlGroup.LinkLabel>
        ) : (
          <EnterpriseControlGroup.Button
            disabled={disableAction}
            variant="invisible"
            onClick={createRuleset}
            loading={isLoading}
          >
            Create ruleset
          </EnterpriseControlGroup.Button>
        )}
      </EnterpriseControlGroup.Item>
    </EnterpriseControlGroup>
  )
}

function RulesetSummary({ruleset}: {ruleset?: Ruleset}) {
  if (!ruleset) {
    return <span>Create a ruleset that only allows enterprise admins to edit agent source code.</span>
  }
  return (
    <div className="d-flex gap-1">
      <span>Ruleset</span>
      <span>•</span>
      <span>1 push rule</span>
      <span>•</span>
      <span>targeting all repositories</span>
    </div>
  )
}

const enforcementMap: Record<
  Enforcement,
  {
    Icon: PrimerIcon
    color: string
  }
> = {
  enabled: {
    Icon: PlayIcon,
    color: 'color-fg-success',
  },
  disabled: {
    Icon: SkipIcon,
    color: 'color-fg-muted',
  },
  evaluate: {
    Icon: MeterIcon,
    color: 'color-fg-attention',
  },
}

function RulesetEnforcement({ruleset}: {ruleset?: Ruleset}) {
  if (!ruleset) {
    return <ShieldIcon size="small" />
  }
  const {Icon, color} = enforcementMap[ruleset.enforcement]
  return <Icon size="small" className={color} />
}

try{ ProtectAgents.displayName ||= 'ProtectAgents' } catch {}
try{ RulesetSummary.displayName ||= 'RulesetSummary' } catch {}
try{ RulesetEnforcement.displayName ||= 'RulesetEnforcement' } catch {}