import {mainQuery} from '@github-ui/react-core/future/main-query'
import {copilotAgentPlaneAppBuilder} from '../config/app-builder'

export type SessionData = {
  id: string
  status: string
  status_display: string
  status_icon: string
  title: string
  url?: string
  repository: {
    owner: string
    name: string
    full_name: string
  }
  started_at: string
  time_since_start: string
  event_type?: string
}

export type PaginationData = {
  current_page: number
  total_pages: number
  total_count: number
  per_page: number
  has_previous: boolean
  has_next: boolean
}

export type SessionsResponse = {
  sessions: SessionData[]
  pagination: PaginationData
  heading: string
}

export const sessionsRoute = copilotAgentPlaneAppBuilder.createQueryRouteConfig('sessionsRoute', {
  path: '/enterprises/:slug/ai-controls/agents/sessions',
  queries: [mainQuery<SessionsResponse>()],
})
