import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {SessionsData} from './use-custom-agents'

export function useRecentSessions({slug, limit = 3}: {slug: string; limit?: number}) {
  const {data, isLoading, error} = useQuery({
    queryKey: ['copilot-agent-plane', 'recent-sessions', slug, limit],
    queryFn: async () => {
      const url = new URL(`/enterprises/${slug}/ai-controls/agents/sessions`, window.location.origin)
      url.searchParams.set('page', '1')
      url.searchParams.set('per_page', limit.toString())
      const response = await verifiedFetchJSON(url.toString())
      const json = await response.json()

      // Check if the response is wrapped in a payload structure
      if (json?.payload?.sessionsRoute) {
        return json.payload.sessionsRoute as SessionsData
      }

      // Otherwise return the json directly
      return json as SessionsData
    },
    // Add retry and error handling
    retry: 1,
    staleTime: 30000, // Cache for 30 seconds
  })

  return {data, isLoading, error}
}
