import {useCallback, useMemo, useState} from 'react'
import {useQueryClient, useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import type {AppPayload, Ruleset} from '../types'
import {usePageBanner} from '../contexts/PageBannerContext'

export function useRuleset() {
  const {paths} = useAppPayload<AppPayload>()
  const queryClient = useQueryClient()
  const queryKey = useMemo(() => ['copilot-agent-plane', 'ruleset', paths.showRuleset], [paths.showRuleset])
  const {
    isLoading,
    data: ruleset,
    refetch: refetchRuleset,
  } = useQuery({
    queryKey,
    queryFn: async () => {
      const response = await verifiedFetchJSON(paths.showRuleset)

      if (!response.ok) {
        throw new Error(`Failed to fetch ruleset (${response.status} on ${response.url})`)
      }

      const json = await response.json()
      if (!json.success) {
        throw new Error(`Failed to fetch ruleset: ${json.message}`)
      }

      return json.ruleset as Ruleset
    },
  })
  const {setBanner} = usePageBanner()

  const [isCreating, setIsCreating] = useState(false)
  const createRuleset = useCallback(async () => {
    setIsCreating(true)
    try {
      const response = await verifiedFetchJSON(paths.createRuleset, {
        method: 'POST',
      })
      if (response.ok) {
        const {ruleset: newRuleset} = await response.json()
        queryClient.setQueryData(queryKey, () => newRuleset)
        setBanner({
          type: 'success',
          title: 'Ruleset created',
          message: <span>Successfully enabled custom agents for all members of your enterprise.</span>,
        })
      } else {
        setBanner({
          type: 'critical',
          title: 'Error creating ruleset',
          message: <span>There was a problem generating your ruleset.</span>,
        })
      }
    } finally {
      setIsCreating(false)
    }
  }, [paths.createRuleset, queryClient, queryKey, setBanner])

  return useMemo(
    () => ({
      isLoading: isLoading || isCreating,
      ruleset,
      createRuleset,
      refetchRuleset,
    }),
    [isLoading, isCreating, ruleset, createRuleset, refetchRuleset],
  )
}
