import {mainQuery} from '@github-ui/react-core/future/main-query'
import {copilotAgentPlaneAppBuilder} from '../config/app-builder'

export type Agent = {
  name: string
  enabled: boolean
  policy?: string
}

export type SourceOrg = {
  id: number | null
  name: string | null
  avatar_url: string | null
}

export type CustomAgent = {
  name: string
  repo_owner: string
  repo_name: string
  url: string
}

export type ThirdPartyAgent = {
  name: string
  enabled: boolean
  doc_url: string
  toggle_url: string
}

export type AgentsResponse = {
  agents: Agent[]
  third_party_agents?: ThirdPartyAgent[]
  source_org: SourceOrg
  can_write: boolean
  can_admin: boolean
  can_view_audit_logs: boolean
}

export const agentsRoute = copilotAgentPlaneAppBuilder.createQueryRouteConfig('agentsRoute', {
  path: '/enterprises/:slug/ai-controls/agents',
  queries: [mainQuery<AgentsResponse>()],
})
