import {TriangleDownIcon, XIcon} from '@primer/octicons-react'
import {ActionList, Button, SelectPanel, Spinner, Truncate} from '@primer/react'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useState, useMemo} from 'react'
import {useSuggestedOrgs, setAndValidateOrgForCustomAgents, unsetOrgForCustomAgents} from '../hooks/use-custom-agents'
import {useDebounce} from '@github-ui/use-debounce'
import type {SuggestedOrg, ConfirmationDialogType} from '../types'
import {OrgConfirmationDialog} from './OrgConfirmationDialog'
import {usePageBanner} from '../contexts/PageBannerContext'

type ItemInput = {id?: string | number}

export function SelectOrgPicker(props: {
  selection: SuggestedOrg | null
  onChange: (org: SuggestedOrg | null) => void
  onValidation?: (isValid: boolean) => void
  onValidationLoading?: (loading: boolean) => void
  enterpriseId?: string | number
  slug: string
  disabled?: boolean
}) {
  const {selection, onChange, onValidation, onValidationLoading, slug, disabled} = props
  const {setBanner} = usePageBanner()
  const [open, setOpen] = useState(false)
  const [filter, setFilter] = useState('')
  const [confirmationDialog, setConfirmationDialog] = useState<{
    isOpen: boolean
    type: ConfirmationDialogType
    newOrg?: SuggestedOrg
    currentOrgName?: string
  }>({
    isOpen: false,
    type: 'change',
  })
  const {
    data: suggestions = [],
    isLoading,
    error,
  } = useSuggestedOrgs({
    slug,
    filter,
  })

  const suggestionItems = useMemo(() => {
    const orgItems = suggestions.map((s: SuggestedOrg) => ({
      id: String(s.id),
      text: s.name,
    }))

    if (selection) {
      return [
        {
          id: 'clear-selection',
          text: 'Clear selection',
        },
        ...orgItems,
      ]
    }

    return orgItems
  }, [suggestions, selection])

  const handleSelect = async (item: ItemInput | undefined) => {
    const id = item && 'id' in item ? item.id : undefined
    if (!id) {
      const currentSelection = selection
      onChange(null)
      onValidationLoading?.(true)
      setOpen(false)
      try {
        const result = await unsetOrgForCustomAgents({slug})
        if (result && result.success !== false) {
          onValidation?.(true) // Clear validation banner on success
          setBanner({
            type: 'success',
            title: 'Organization cleared',
            message: <span>Successfully removed the custom agents source organization.</span>,
          })
        } else {
          onChange(currentSelection)
          onValidation?.(false)
          setBanner({
            type: 'critical',
            title: 'Error clearing organization',
            message: <span>There was a problem removing the organization.</span>,
          })
        }
      } catch {
        onChange(currentSelection)
        onValidation?.(false)
        setBanner({
          type: 'critical',
          title: 'Error clearing organization',
          message: <span>There was a problem removing the organization.</span>,
        })
      } finally {
        onValidationLoading?.(false)
      }
      return
    }

    // Handle "Clear selection" item
    if (id === 'clear-selection') {
      setConfirmationDialog({
        isOpen: true,
        type: 'unset',
        currentOrgName: selection?.name || '',
      })
      setOpen(false)
      return
    }

    const org = suggestions.find((s: SuggestedOrg) => String(s.id) === String(id))

    if (!org) {
      onChange(null)
      onValidation?.(true)
      unsetOrgForCustomAgents({slug})
      setOpen(false)
      return
    }

    if (selection && selection.id === org.id) {
      setOpen(false)
      return
    }

    if (selection && selection.id !== org.id) {
      setConfirmationDialog({
        isOpen: true,
        type: 'change',
        newOrg: org,
        currentOrgName: selection.name,
      })
      setOpen(false)
      return
    }

    if (!selection) {
      setConfirmationDialog({
        isOpen: true,
        type: 'set',
        newOrg: org,
      })
      setOpen(false)
      return
    }
    setOpen(false)
  }

  const confirmOrgChange = async (org: SuggestedOrg) => {
    const currentSelection = selection
    onChange(org)
    onValidationLoading?.(true)
    try {
      const result = await setAndValidateOrgForCustomAgents({organizationId: org.id, slug})
      if (result.success) {
        onValidation?.(true)
        setBanner({
          type: 'success',
          title: 'Organization selected',
          message: <span>Successfully set {org.name} as your custom agents source organization.</span>,
        })
      } else {
        onChange(currentSelection)
        onValidation?.(false)
      }
    } catch {
      onChange(currentSelection)
      onValidation?.(false)
      setBanner({
        type: 'critical',
        title: 'Error selecting organization',
        message: <span>There was a problem setting the organization.</span>,
      })
    } finally {
      onValidationLoading?.(false)
    }
  }

  const confirmOrgUnset = async () => {
    const currentSelection = selection
    onChange(null)
    onValidationLoading?.(true)
    try {
      const result = await unsetOrgForCustomAgents({slug})
      if (result && result.success !== false) {
        onValidation?.(true) // Clear validation banner on success
        setBanner({
          type: 'success',
          title: 'Organization cleared',
          message: <span>Successfully removed the custom agents source organization.</span>,
        })
      } else {
        onChange(currentSelection)
        onValidation?.(false)
        setBanner({
          type: 'critical',
          title: 'Error clearing organization',
          message: <span>There was a problem removing the organization.</span>,
        })
      }
    } catch {
      onChange(currentSelection)
      onValidation?.(false)
      setBanner({
        type: 'critical',
        title: 'Error clearing organization',
        message: <span>There was a problem removing the organization.</span>,
      })
    } finally {
      onValidationLoading?.(false)
    }
  }

  const handleConfirmation = async () => {
    if (confirmationDialog.type === 'change' && confirmationDialog.newOrg) {
      await confirmOrgChange(confirmationDialog.newOrg)
    } else if (confirmationDialog.type === 'set' && confirmationDialog.newOrg) {
      await confirmOrgChange(confirmationDialog.newOrg)
    } else if (confirmationDialog.type === 'unset') {
      await confirmOrgUnset()
    }
    setConfirmationDialog({isOpen: false, type: 'change'})
  }

  const handleCancelConfirmation = () => {
    setConfirmationDialog({isOpen: false, type: 'change'})
  }

  return (
    <>
      <SelectPanel
        items={suggestionItems}
        selected={selection ? {id: String(selection.id)} : undefined}
        renderAnchor={anchorProps => (
          <Button {...anchorProps} trailingAction={TriangleDownIcon} aria-haspopup="dialog" disabled={disabled}>
            {selection ? (
              <Truncate title={selection.name} inline maxWidth="230px">
                Selected organization: {selection.name}
              </Truncate>
            ) : (
              'Select organization'
            )}
          </Button>
        )}
        onSelectedChange={(item: ItemInput | undefined) => handleSelect(item)}
        open={open}
        onOpenChange={setOpen}
        onFilterChange={useDebounce(setFilter, 300)}
        placeholder={selection ? selection?.name : 'Select organization'}
        renderItem={item => {
          if (item.id === 'clear-selection') {
            return (
              <ActionList.Item
                {...item}
                key={String(item.id)}
                id={String(item.id)}
                onSelect={(e: React.MouseEvent<HTMLElement> | React.KeyboardEvent<HTMLElement>) => {
                  handleSelect(item)
                  item.onAction?.(item, e as React.MouseEvent<HTMLDivElement> | React.KeyboardEvent<HTMLDivElement>)
                }}
                selected={false}
                className="d-flex align-items-center justify-content-between gap-2 fgColor-danger"
              >
                <div className="d-flex align-items-center fgColor-danger">
                  <span className="mr-2">
                    <XIcon size={16} />
                  </span>
                  Clear selection
                </div>
              </ActionList.Item>
            )
          }

          const org = suggestions.find((s: SuggestedOrg) => String(s.id) === String(item.id))
          return (
            <ActionList.Item
              {...item}
              id={String(item.id)}
              onSelect={(e: React.MouseEvent<HTMLElement> | React.KeyboardEvent<HTMLElement>) => {
                handleSelect(item)
                item.onAction?.(item, e as React.MouseEvent<HTMLDivElement> | React.KeyboardEvent<HTMLDivElement>)
              }}
              selected={selection ? String(selection.id) === String(item.id) : false}
              className="d-flex align-items-center justify-content-between gap-2"
            >
              <div className="d-flex align-items-center">
                {org?.primaryAvatarUrl && (
                  <GitHubAvatar alt={item.text} src={org.primaryAvatarUrl} square size={20} className="mr-2" />
                )}
                {item.text}
              </div>
            </ActionList.Item>
          )
        }}
        message={
          isLoading
            ? {
                title: '',
                body: <Spinner size="medium" />,
                variant: 'empty',
              }
            : error
              ? {
                  title: 'Error',
                  body: <span>Failed to load organizations.</span>,
                  variant: 'error',
                }
              : undefined
        }
        footer={undefined}
      />

      <OrgConfirmationDialog
        isOpen={confirmationDialog.isOpen}
        type={confirmationDialog.type}
        newOrg={confirmationDialog.newOrg}
        currentOrgName={confirmationDialog.currentOrgName}
        onConfirm={handleConfirmation}
        onCancel={handleCancelConfirmation}
      />
    </>
  )
}

try{ SelectOrgPicker.displayName ||= 'SelectOrgPicker' } catch {}