import {ClockIcon, CheckCircleFillIcon, XCircleFillIcon, SkipIcon} from '@primer/octicons-react'

export function InProgressSpinner() {
  return (
    <svg
      aria-label="Currently running"
      width="16px"
      height="16px"
      fill="none"
      viewBox="0 0 16 16"
      className="anim-rotate"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        fill="none"
        stroke="var(--color-fg-attention, #bf8700)"
        strokeWidth="2"
        d="M3.05 3.05a7 7 0 1 1 9.9 9.9 7 7 0 0 1-9.9-9.9Z"
        opacity=".5"
      />
      <path
        fill="var(--color-fg-attention, #bf8700)"
        fillRule="evenodd"
        d="M8 4a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"
        clipRule="evenodd"
      />
      <path fill="var(--color-fg-attention, #bf8700)" d="M14 8a6 6 0 0 0-6-6V0a8 8 0 0 1 8 8h-2Z" />
    </svg>
  )
}

export const getStatusIcon = (status: string) => {
  switch (status) {
    case 'queued':
      return <ClockIcon className="fgColor-attention" aria-label="Queued" />
    case 'in_progress':
      return <InProgressSpinner />
    case 'waiting_for_user':
    case 'idle':
      return <InProgressSpinner />
    case 'completed':
      return <CheckCircleFillIcon className="fgColor-success" aria-label="Done" />
    case 'failed':
      return <XCircleFillIcon className="fgColor-danger" aria-label="Failed" />
    case 'timed_out':
      return <XCircleFillIcon className="fgColor-danger" aria-label="Timed out" />
    case 'cancelled':
      return <SkipIcon className="fgColor-neutral" aria-label="User cancelled" />
    default:
      return <InProgressSpinner />
  }
}

export const getStatusProgress = (status: string) => {
  switch (status) {
    case 'queued':
      return 10
    case 'in_progress':
      return 50
    case 'waiting_for_user':
      return 60
    case 'idle':
      return 30
    case 'completed':
      return 100
    case 'failed':
    case 'timed_out':
    case 'cancelled':
      return 100
    default:
      return 0
  }
}

try{ InProgressSpinner.displayName ||= 'InProgressSpinner' } catch {}