import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {sessionsRoute} from './sessions-route'
import {ArrowLeftIcon, FilterIcon} from '@primer/octicons-react'
import {Link, PageHeader, Pagination, Stack, ActionMenu, ActionList, TextInput} from '@primer/react'
import {EnterpriseControlGroup} from '@github-ui/enterprise-control-group'
import {useState, useMemo, useEffect} from 'react'
import {getStatusIcon, getStatusProgress} from '../components/IconStatus'

export function Sessions() {
  const {data: payload} = useRouteQuery(sessionsRoute, 'mainQuery')
  const [currentPage, setCurrentPage] = useState(1)
  const SessionType = {
    CodingSession: 'coding_session',
    CodeReview: 'code_review',
    All: 'all',
  } as const
  type SessionType = (typeof SessionType)[keyof typeof SessionType]

  const [selectedOrganization, setSelectedOrganization] = useState<string>('all')
  const [selectedSessionType, setSelectedSessionType] = useState<SessionType>(SessionType.CodingSession)
  const [searchQuery, setSearchQuery] = useState('')
  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState('')
  const itemsPerPage = 10

  // Debounce search query to avoid filtering on every keystroke
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchQuery(searchQuery)
    }, 300)

    return () => clearTimeout(timer)
  }, [searchQuery])

  // Get unique organizations from sessions
  const organizations: string[] = useMemo(
    () => Array.from(new Set(payload.sessions.map(session => session.repository.owner))).sort(),
    [payload.sessions],
  )

  const getSessionCategory = (eventType?: string): string => {
    if (eventType === 'pull_request_comment' || eventType === 'pull_request_review') {
      return SessionType.CodeReview
    }
    return SessionType.CodingSession
  }

  let filteredSessions = payload.sessions

  if (selectedOrganization !== 'all') {
    filteredSessions = filteredSessions.filter(session => session.repository.owner === selectedOrganization)
  }

  if (selectedSessionType !== SessionType.All) {
    filteredSessions = filteredSessions.filter(
      session => getSessionCategory(session.event_type) === selectedSessionType,
    )
  }

  const filteredOrganizations = useMemo(() => {
    if (!debouncedSearchQuery) return organizations
    return organizations.filter(org => org.toLowerCase().includes(debouncedSearchQuery.toLowerCase()))
  }, [organizations, debouncedSearchQuery])

  const totalSessions = filteredSessions.length
  const totalPages = Math.ceil(totalSessions / itemsPerPage)

  // Ensure current page doesn't exceed total pages
  const validCurrentPage = Math.min(currentPage, Math.max(1, totalPages))

  // Calculate the start and end index for the current page
  const startIndex = (validCurrentPage - 1) * itemsPerPage
  const endIndex = startIndex + itemsPerPage
  const currentSessions = filteredSessions.slice(startIndex, endIndex)

  const handlePageChange = (e: React.MouseEvent | React.KeyboardEvent, page: number) => {
    e.preventDefault()
    setCurrentPage(page)
  }

  const handleOrganizationSelect = (org: string) => {
    setSelectedOrganization(org)
    setCurrentPage(1) // Reset to first page when filter changes
  }

  const handleSessionTypeSelect = (type: SessionType) => {
    setSelectedSessionType(type)
    setCurrentPage(1) // Reset to first page when filter changes
  }

  return (
    <Stack>
      <Link href="..">
        <ArrowLeftIcon /> Agents
      </Link>
      <PageHeader>
        <PageHeader.TitleArea>
          <PageHeader.Title as="h2">
            Agent sessions
            <span className="ml-2 text-small fgColor-muted" style={{fontWeight: 'lighter'}}>
              Last 24 hours
            </span>
          </PageHeader.Title>
        </PageHeader.TitleArea>
        <PageHeader.Actions>
          <ActionMenu>
            <ActionMenu.Button leadingVisual={FilterIcon}>
              {selectedSessionType === SessionType.CodingSession
                ? 'Coding session'
                : selectedSessionType === SessionType.CodeReview
                  ? 'Code review'
                  : 'All sessions'}
            </ActionMenu.Button>
            <ActionMenu.Overlay>
              <ActionList selectionVariant="single">
                <ActionList.Item
                  selected={selectedSessionType === SessionType.CodingSession}
                  onSelect={() => handleSessionTypeSelect(SessionType.CodingSession)}
                >
                  Coding session
                </ActionList.Item>
                <ActionList.Item
                  selected={selectedSessionType === SessionType.CodeReview}
                  onSelect={() => handleSessionTypeSelect(SessionType.CodeReview)}
                >
                  Code review
                </ActionList.Item>
                <ActionList.Item
                  selected={selectedSessionType === SessionType.All}
                  onSelect={() => handleSessionTypeSelect(SessionType.All)}
                >
                  All sessions
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
          <ActionMenu>
            <ActionMenu.Button leadingVisual={FilterIcon}>
              {selectedOrganization === 'all' ? 'All organizations' : selectedOrganization}
            </ActionMenu.Button>
            <ActionMenu.Overlay>
              <ActionList selectionVariant="single">
                <ActionList.Group>
                  <ActionList.GroupHeading>Filter by organization</ActionList.GroupHeading>
                  {organizations.length > 3 && (
                    <div className="px-2 py-1">
                      <TextInput
                        placeholder="Search organizations..."
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        size="small"
                        className="width-full"
                        aria-label="Search organizations"
                        role="searchbox"
                      />
                    </div>
                  )}
                  <ActionList.Item
                    selected={selectedOrganization === 'all'}
                    onSelect={() => handleOrganizationSelect('all')}
                  >
                    All organizations
                  </ActionList.Item>
                </ActionList.Group>
                {organizations.length > 0 && (
                  <ActionList.Group>
                    <ActionList.Divider />
                    {filteredOrganizations.length > 0 ? (
                      filteredOrganizations.map(org => (
                        <ActionList.Item
                          key={org}
                          selected={selectedOrganization === org}
                          onSelect={() => handleOrganizationSelect(org)}
                        >
                          {org}
                        </ActionList.Item>
                      ))
                    ) : (
                      <ActionList.Item disabled>No matching organizations</ActionList.Item>
                    )}
                  </ActionList.Group>
                )}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </PageHeader.Actions>
      </PageHeader>

      <Stack>
        {filteredSessions.length === 0 ? (
          <div className="Box-row py-6 text-center fgColor-muted">
            {payload.sessions.length === 0
              ? 'No agent sessions found.'
              : (() => {
                  const filters = []
                  if (selectedSessionType !== SessionType.All) {
                    filters.push(
                      selectedSessionType === SessionType.CodeReview ? 'code review sessions' : 'coding sessions',
                    )
                  }
                  if (selectedOrganization !== 'all') {
                    filters.push(`organization "${selectedOrganization}"`)
                  }
                  return filters.length > 0
                    ? `No agent sessions found for ${filters.join(' and ')}.`
                    : 'No agent sessions found.'
                })()}
          </div>
        ) : (
          <>
            <EnterpriseControlGroup>
              {currentSessions.map(session => {
                return (
                  <EnterpriseControlGroup.Item
                    key={session.id}
                    customLeadingVisual={
                      <div className="pr-3" style={{paddingLeft: '2px', paddingTop: '1px'}}>
                        {getStatusIcon(session.status)}
                      </div>
                    }
                  >
                    <EnterpriseControlGroup.Title>
                      {session.url ? (
                        <Link href={session.url} className="Link--primary no-underline">
                          {session.title}
                        </Link>
                      ) : (
                        <span>{session.title}</span>
                      )}
                    </EnterpriseControlGroup.Title>
                    <EnterpriseControlGroup.Description>
                      <div className="text-small fgColor-muted">
                        <Link href={`/${session.repository.full_name}`} className="Link--muted">
                          {session.repository.full_name}
                        </Link>
                        <span className="mx-1">·</span>
                        <span>Started {session.time_since_start}</span>
                      </div>
                    </EnterpriseControlGroup.Description>
                    <EnterpriseControlGroup.Custom>
                      <div className="d-flex flex-row flex-items-center gap-2">
                        <span className="text-small">{session.status_display}</span>
                        <div className="Progress" style={{width: '105px', height: '3px', marginTop: '2px'}}>
                          <div
                            className="Progress-item"
                            style={{
                              width: `${getStatusProgress(session.status)}%`,
                              backgroundColor: 'var(--bgColor-accent-emphasis)',
                            }}
                          />
                        </div>
                      </div>
                    </EnterpriseControlGroup.Custom>
                  </EnterpriseControlGroup.Item>
                )
              })}
            </EnterpriseControlGroup>
            <Pagination
              pageCount={totalPages}
              currentPage={validCurrentPage}
              onPageChange={handlePageChange}
              showPages
              surroundingPageCount={2}
            />
          </>
        )}
      </Stack>
    </Stack>
  )
}

try{ Sessions.displayName ||= 'Sessions' } catch {}