import {Banner as PrimerBanner} from '@primer/react'
import {usePageBanner} from '../contexts/PageBannerContext'

export function PageBanner() {
  const {banner, clearBanner} = usePageBanner()

  if (!banner) {
    return null
  }

  return (
    <PrimerBanner hideTitle title={banner.title} variant={banner.type} onDismiss={clearBanner}>
      <PrimerBanner.Description>{banner.message}</PrimerBanner.Description>
    </PrimerBanner>
  )
}

try{ PageBanner.displayName ||= 'PageBanner' } catch {}